import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    include: ["__tests__/**/*.test.ts"],
  },
});

export interface PostFrontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  layout?: string;
  [key: string]: unknown;
}

export interface Post {
  slug: string;
  sourcePath: string;
  frontmatter: PostFrontmatter;
  body: string;
  html: string;
  url: string;
}

export interface TagIndex {
  tag: string;
  posts: Post[];
  url: string;
}

export interface SiteConfig {
  title: string;
  description: string;
  url: string;
  author?: string;
  language?: string;
}

export interface BuildContext {
  posts: Post[];
  tags: TagIndex[];
  config: SiteConfig;
  sourceDir: string;
  templateDir: string;
  outputDir: string;
}

import * as fs from "fs";
import * as path from "path";
import * as yaml from "js-yaml";
import { PostFrontmatter, Post } from "./types";

interface FrontmatterResult {
  attributes: PostFrontmatter;
  body: string;
}

export function parseFrontmatter(source: string): FrontmatterResult {
  const lines = source.split("\n");
  if (lines[0]?.trim() !== "---") {
    return { attributes: { title: "" }, body: source };
  }

  let end = 0;
  for (let i = 1; i < lines.length; i++) {
    if (lines[i]?.trim() === "---") {
      end = i;
      break;
    }
  }

  if (end === 0) {
    return { attributes: { title: "" }, body: source };
  }

  const yamlBlock = lines.slice(1, end).join("\n");
  const body = lines.slice(end + 1).join("\n");

  const attributes = yaml.load(yamlBlock) as PostFrontmatter;
  return {
    attributes: attributes || { title: "" },
    body: body.trimStart(),
  };
}

function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    || "post";
}

export function parseMarkdownFile(filePath: string, sourceDir: string): Post {
  const raw = fs.readFileSync(filePath, "utf-8");
  const { attributes: frontmatter, body } = parseFrontmatter(raw);

  const relPath = path.relative(sourceDir, filePath);
  const parsedPath = path.parse(relPath);
  const dirName = parsedPath.dir ? parsedPath.dir.replace(/\\/g, "/") : "";
  const baseName = parsedPath.name;

  const slugBase = frontmatter.title ? slugify(frontmatter.title) : slugify(baseName);
  const slug = dirName ? `${dirName}/${slugBase}` : slugBase;

  return {
    slug,
    sourcePath: filePath,
    frontmatter,
    body,
    html: "",
    url: `/${slug}.html`,
  };
}

export function collectPosts(sourceDir: string): Post[] {
  const files = walkDir(sourceDir);
  const mdFiles = files.filter(
    (f) => f.endsWith(".md") || f.endsWith(".markdown")
  );
  return mdFiles.map((f) => parseMarkdownFile(f, sourceDir));
}

function walkDir(dir: string): string[] {
  const results: string[] = [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.name.startsWith(".") || entry.name.startsWith("_")) continue;
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...walkDir(fullPath));
    } else {
      results.push(fullPath);
    }
  }
  return results;
}

import * as fs from "fs";
import * as path from "path";
import Handlebars from "handlebars";

export function registerPartials(templateDir: string): void {
  const partialsDir = path.join(templateDir, "partials");
  if (!fs.existsSync(partialsDir)) return;

  const files = fs.readdirSync(partialsDir);
  for (const file of files) {
    if (file.endsWith(".hbs") || file.endsWith(".handlebars")) {
      const name = path.basename(file, path.extname(file));
      const content = fs.readFileSync(path.join(partialsDir, file), "utf-8");
      Handlebars.registerPartial(name, content);
    }
  }
}

export function loadTemplate(
  templateDir: string,
  name: string
): HandlebarsTemplateDelegate {
  const templatePath = path.join(templateDir, `${name}.hbs`);

  if (!fs.existsSync(templatePath)) {
    throw new Error(`Template not found: ${templatePath}`);
  }

  const source = fs.readFileSync(templatePath, "utf-8");
  return Handlebars.compile(source);
}

export function renderWithLayout(
  templateDir: string,
  contentHtml: string,
  pageData: Record<string, unknown>,
  layoutName?: string
): string {
  const layout = layoutName || "default";

  try {
    const layoutTemplate = loadTemplate(templateDir, `layouts/${layout}`);
    return layoutTemplate({ ...pageData, content: contentHtml });
  } catch {
    return contentHtml;
  }
}

export function renderTemplate(
  templateDir: string,
  templateName: string,
  data: Record<string, unknown>,
  layoutName?: string
): string {
  const template = loadTemplate(templateDir, templateName);
  const content = template(data);
  return renderWithLayout(templateDir, content, data, layoutName);
}

export function registerHelpers(): void {
  Handlebars.registerHelper("formatDate", (date: string) => {
    if (!date) return "";
    const d = new Date(date);
    if (isNaN(d.getTime())) return date;
    return d.toLocaleDateString("en-US", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  });

  Handlebars.registerHelper("isoDate", (date: string) => {
    if (!date) return "";
    const d = new Date(date);
    if (isNaN(d.getTime())) return "";
    return d.toISOString();
  });

  Handlebars.registerHelper("rfc822Date", (date: string) => {
    if (!date) return "";
    const d = new Date(date);
    if (isNaN(d.getTime())) return "";
    return d.toUTCString();
  });

  Handlebars.registerHelper("encodeURI", (str: string) => {
    return encodeURI(str);
  });
}

import { marked, MarkedExtension } from "marked";
import hljs from "highlight.js";

export function initMarked(): void {
  const renderer = new marked.Renderer();

  renderer.code = function ({ text, lang }: { text: string; lang?: string }): string {
    if (lang && hljs.getLanguage(lang)) {
      try {
        const highlighted = hljs.highlight(text, { language: lang }).value;
        return `<pre><code class="hljs language-${lang}">${highlighted}</code></pre>`;
      } catch {
        // fall through
      }
    }
    return `<pre><code>${escapeHtml(text)}</code></pre>`;
  };

  marked.setOptions({
    renderer,
    gfm: true,
    breaks: false,
  });
}

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

export function markdownToHtml(markdown: string): string {
  const result = marked.parse(markdown);
  if (typeof result === "string") return result;
  return result.then ? "" : result as unknown as string;
}

import RSS from "rss";
import { BuildContext, Post } from "./types";

export function generateRssFeed(ctx: BuildContext): string {
  const published = ctx.posts.filter((p) => !p.frontmatter.draft);
  published.sort((a, b) => {
    const da = a.frontmatter.date ? new Date(a.frontmatter.date).getTime() : 0;
    const db = b.frontmatter.date ? new Date(b.frontmatter.date).getTime() : 0;
    return db - da;
  });

  const feed = new RSS({
    title: ctx.config.title,
    description: ctx.config.description,
    site_url: ctx.config.url,
    feed_url: `${ctx.config.url}/rss.xml`,
    language: ctx.config.language || "en",
    pubDate: published.length > 0
      ? published[0].frontmatter.date || new Date().toISOString()
      : new Date().toISOString(),
  });

  for (const post of published.slice(0, 20)) {
    feed.item({
      title: post.frontmatter.title || post.slug,
      description: post.html,
      url: `${ctx.config.url}${post.url}`,
      date: post.frontmatter.date || new Date().toISOString(),
      categories: post.frontmatter.tags,
    });
  }

  return feed.xml({ indent: true });
}

import * as fs from "fs";
import * as path from "path";
import { BuildContext, Post, TagIndex, SiteConfig } from "./types";
import { collectPosts } from "./parser";
import { initMarked, markdownToHtml } from "./markdown";
import { registerPartials, registerHelpers, renderTemplate } from "./template";
import { generateRssFeed } from "./rss";

export function loadConfig(sourceDir: string): SiteConfig {
  const configPath = path.join(sourceDir, "config.yaml");
  const defaults: SiteConfig = {
    title: path.basename(path.resolve(sourceDir)),
    description: "",
    url: "http://localhost:3000",
  };

  if (!fs.existsSync(configPath)) return defaults;

  try {
    const yaml = require("js-yaml");
    const raw = fs.readFileSync(configPath, "utf-8");
    const userConfig = yaml.load(raw) as Partial<SiteConfig>;
    return { ...defaults, ...userConfig };
  } catch {
    return defaults;
  }
}

export function buildPosts(posts: Post[]): Post[] {
  for (const post of posts) {
    post.html = markdownToHtml(post.body);
  }
  return posts;
}

export function buildTagIndexes(posts: Post[]): TagIndex[] {
  const published = posts.filter((p) => !p.frontmatter.draft);
  const tagMap = new Map<string, Post[]>();

  for (const post of published) {
    const tags = post.frontmatter.tags || [];
    for (const tag of tags) {
      if (!tagMap.has(tag)) tagMap.set(tag, []);
      tagMap.get(tag)!.push(post);
    }
  }

  const indexes: TagIndex[] = [];
  for (const [tag, tagPosts] of tagMap) {
    indexes.push({
      tag,
      posts: tagPosts,
      url: `/tags/${slugifyTag(tag)}.html`,
    });
  }
  return indexes;
}

function slugifyTag(tag: string): string {
  return tag
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

export function buildSite(sourceDir: string, templateDir: string, outputDir: string): BuildContext {
  registerHelpers();
  registerPartials(templateDir);
  initMarked();

  const config = loadConfig(sourceDir);
  const posts = collectPosts(sourceDir);
  buildPosts(posts);
  const tags = buildTagIndexes(posts);

  const ctx: BuildContext = {
    posts,
    tags,
    config,
    sourceDir,
    templateDir,
    outputDir,
  };

  writeSite(ctx);
  return ctx;
}

function writeSite(ctx: BuildContext): void {
  if (fs.existsSync(ctx.outputDir)) {
    fs.rmSync(ctx.outputDir, { recursive: true });
  }
  fs.mkdirSync(ctx.outputDir, { recursive: true });

  const published = ctx.posts.filter((p) => !p.frontmatter.draft);
  published.sort((a, b) => {
    const da = a.frontmatter.date ? new Date(a.frontmatter.date).getTime() : 0;
    const db = b.frontmatter.date ? new Date(b.frontmatter.date).getTime() : 0;
    return db - da;
  });

  writeFile(ctx, "index.html", renderTemplate(ctx.templateDir, "index", {
    posts: published,
    config: ctx.config,
  }));

  for (const post of published) {
    const layout = post.frontmatter.layout;
    const html = renderTemplate(ctx.templateDir, "post", {
      post,
      config: ctx.config,
    }, layout);
    writeFile(ctx, post.url, html);
  }

  const tagsDir = path.join(ctx.outputDir, "tags");
  fs.mkdirSync(tagsDir, { recursive: true });
  for (const tagIdx of ctx.tags) {
    const html = renderTemplate(ctx.templateDir, "tag", {
      tag: tagIdx,
      posts: tagIdx.posts,
      config: ctx.config,
    });
    writeFile(ctx, tagIdx.url, html);
  }

  const tagsPage = renderTemplate(ctx.templateDir, "tags-index", {
    tags: ctx.tags,
    config: ctx.config,
  });
  writeFile(ctx, "/tags.html", tagsPage);

  const rssXml = generateRssFeed(ctx);
  writeRaw(ctx, "/rss.xml", rssXml);

  copyStatic(ctx);
}

function writeFile(ctx: BuildContext, url: string, html: string): void {
  const filePath = path.join(ctx.outputDir, url.replace(/^\//, ""));
  const dir = path.dirname(filePath);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(filePath, html, "utf-8");
}

function writeRaw(ctx: BuildContext, url: string, content: string): void {
  const filePath = path.join(ctx.outputDir, url.replace(/^\//, ""));
  const dir = path.dirname(filePath);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(filePath, content, "utf-8");
}

function copyStatic(ctx: BuildContext): void {
  const staticDir = path.join(ctx.sourceDir, "static");
  if (!fs.existsSync(staticDir)) return;
  copyDir(staticDir, ctx.outputDir);
}

function copyDir(src: string, dest: string): void {
  fs.mkdirSync(dest, { recursive: true });
  const entries = fs.readdirSync(src, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.name.startsWith(".")) continue;
    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);
    if (entry.isDirectory()) {
      copyDir(srcPath, destPath);
    } else {
      fs.copyFileSync(srcPath, destPath);
    }
  }
}

